const BOOK_MEMBER_FACTOR = 0.9;
const DEFAULT_MEMBER_FACTOR = 0.95;
const SAVE10_COUPON = "SAVE10";
const SAVE10_DISCOUNT = 10;

function applyMemberDiscount(price: number, category: string): number {
  const factor = category == "books" ? BOOK_MEMBER_FACTOR : DEFAULT_MEMBER_FACTOR;
  return price * factor;
}

function applyCoupon(price: number, coupon?: string): number {
  if (coupon == SAVE10_COUPON) {
    return Math.max(0, price - SAVE10_DISCOUNT);
  }
  return price;
}

function roundToCents(amount: number): number {
  return Math.round(amount * 100) / 100;
}

export function getPrice(p: any, isMember: boolean, coupon?: string) {
  const memberPrice = isMember ? applyMemberDiscount(p.price, p.category) : p.price;
  return roundToCents(applyCoupon(memberPrice, coupon));
}

